#!/usr/bin/env bash
# Real L1 deposit -> Miden mint -> L1 exit with >256 KiB ABI metadata, followed
# by live preimage recovery and missing-row/reset-client restore with stable history.
# Requires an initialized, disposable E2E stack. Restarts only its proxy.
set -euo pipefail
SOURCE_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_DIR="${E2E_PROJECT_DIR:-$(cd "$SOURCE_DIR/.." && pwd)}"
FIXTURES_DIR="$PROJECT_DIR/fixtures"
# Generated by the E2E setup, not committed.
# shellcheck source=/dev/null
source "$FIXTURES_DIR/.env"
export COMPOSE_PROJECT_NAME="${COMPOSE_PROJECT_NAME:-miden-agglayer}"
export AGGLAYER_CONTAINER="${AGGLAYER_CONTAINER:-${COMPOSE_PROJECT_NAME}-miden-agglayer-1}"
export PG_CONTAINER="${PG_CONTAINER:-${COMPOSE_PROJECT_NAME}-agglayer-postgres-1}"
export ISO_NODE_DATA_VOLUME="${ISO_NODE_DATA_VOLUME:-${COMPOSE_PROJECT_NAME}_node_data}"
export L1_RPC="${L1_RPC:-http://localhost:8545}" L2_RPC="${L2_RPC:-http://localhost:8546}"
export MIDEN_NODE_GIT_URL="${MIDEN_NODE_GIT_URL:-https://github.com/0xMiden/node.git}"
export MIDEN_NODE_GIT_REF="${MIDEN_NODE_GIT_REF:-$(sed -n 's/^MIDEN_NODE_GIT_REF *:= *//p' "$PROJECT_DIR/Makefile")}"
export FUNDED_KEY=0x12d7de8621a77640c9241b2595ba78ce443d05e94090365ab3bb5e19df82c625
FUNDED_ADDR="$(cast wallet address --private-key "$FUNDED_KEY")"
export FUNDED_ADDR
export BRIDGE_ADDRESS ADMIN_API_KEY PROJECT_DIR FIXTURES_DIR
export LARGE_METADATA_FIXTURE="$SOURCE_DIR/../fixtures/LargeMetadataToken.sol:LargeMetadataToken"
export NAME_BYTES="${NAME_BYTES:-350000}"
export EVIDENCE_DIR="${EVIDENCE_DIR:-$PROJECT_DIR/out/large-metadata-$(date -u +%Y%m%dT%H%M%SZ)-$$}"
mkdir -p "$EVIDENCE_DIR"
ACCOUNTS=$(docker exec "$AGGLAYER_CONTAINER" cat /var/lib/miden-agglayer-service/bridge_accounts.toml)
BRIDGE_ID=$(printf '%s' "$ACCOUNTS" | sed -n 's/^bridge *= *"\([^"]*\)".*/\1/p')
FAUCET_ETH=$(printf '%s' "$ACCOUNTS" | sed -n 's/^faucet_eth *= *"\([^"]*\)".*/\1/p')
[[ -n "$BRIDGE_ID" && -n "$FAUCET_ETH" ]]
export B2AGG_STORE_DIR="${B2AGG_STORE_DIR:-$PROJECT_DIR/.b2agg-store/e2e-large-metadata-$$}"
source "$PROJECT_DIR/scripts/lib-isolated-wallet.sh"
provision_isolated_wallet "$BRIDGE_ID" "$FAUCET_ETH"
export BRIDGE_ID WALLET_ID DEST_ADDR B2AGG_STORE_DIR
export ISO_IMAGE ISO_NETWORK ISO_NODE_URL ISO_PROVER_URL
export -f _iso_docker_run iso_tool iso_wallet_balance
python3 "$SOURCE_DIR/lib-large-metadata.py"
